public static CustomerDto Map(Customer customer)
{
    var email = customer.Email ?? "no-email";
    var status = customer.Profile switch
    {
        { IsVerified: true } => "verified",
        { Bio.Length: > 0 } => "complete",
        null => "missing",
        _ => "basic"
    };
    return new CustomerDto(customer.Name, email, status);
}
